function classifyDevice(device) {
  const src = (typeof device === "object" && device) || {};
  const ip = String(src.ip || '');
  const mac = String(src.mac || '').toLowerCase();
  const raw = String(src.raw || '').toLowerCase();

  let type = 'Unknown';
  let trusted = true;
  let notes = [];

  if (ip === '255.255.255.255' || ip.endsWith('.255')) {
    type = 'Broadcast Address';
    notes.push('Network broadcast - normal');
    return { ...src, type, trusted, notes: notes.join(', '), needs_review: false };
  }

  if (ip.startsWith('172.')) {
    type = 'WSL/Docker Network';
    notes.push('Virtual network interface');
    return { ...src, type, trusted, notes: notes.join(', '), needs_review: false };
  }

  if (mac === 'ff-ff-ff-ff-ff-ff') {
    type = 'Broadcast MAC';
    notes.push('Network protocol - normal');
    return { ...src, type, trusted, notes: notes.join(', '), needs_review: false };
  }

  if (mac.startsWith('00-15-5d')) {
    type = 'Hyper-V/WSL';
    notes.push('Microsoft virtual adapter');
    return { ...src, type, trusted, notes: notes.join(', '), needs_review: false };
  }

  // Any RFC1918 address is "on this network", whatever the local subnet is.
  if (/^10\./.test(ip) ||
      /^192\.168\./.test(ip) ||
      /^172\.(1[6-9]|2[0-9]|3[01])\./.test(ip)) {
    if (mac === 'unknown') {
