node.warn("request failed: " + (msg.error && msg.error.message));
msg.statusCode = 502;
msg.payload = {
    error: "upstream_request_failed",
    detail: (msg.error && msg.error.message) || "unknown error",
    node: (msg.error && msg.error.source && msg.error.source.name) || ""
};
// SECURITY: msg.headers still holds the OUTBOUND request headers (which carry
// credentials on the error path, because a failed request never overwrites them
// with the upstream response headers). Node-RED's `http response` node sends
// msg.headers back to the caller, so it must be cleared before responding.
delete msg.headers;

return msg;

// One id per health-check run. Fan-out clones inherit it, and both the
// http-request output and the catch path preserve msg properties, so every
// part of this run -- including a branch that errors twice over -- carries
// the same run id for the guard below the probes.
msg.health_tick = msg._msgid + ":" + Date.now();
return msg;

// A failed probe can emit twice: the http request node's own error output
// AND the catch->'branch failed' path, same topic. Two parts for one branch
// desync the count-3 join: it completes early on the real run, then the
// leftover part seeds a second group that fires on the 20s timeout as a
// PARTIAL object -- and the compile step reads the missing branches as
// 'down', reporting services down that are up. Keep the first part per
// (run, branch).
const key = String(msg.health_tick || "no-tick") + "|" + String(msg.topic || "unknown");
const seen = flow.get("health_seen") || {};
const now = Date.now();
for (const k of Object.keys(seen)) {
    if (now - seen[k] > 120000) { delete seen[k]; }  // expire old runs
}
if (seen[key]) { return null; }
seen[key] = now;
flow.set("health_seen", seen);
return msg;

// Correlate the three probe branches BY RUN (health_tick). A stock join
// node keeps one rolling count-3 group shared by every concurrent run, so
// runs would steal each other's parts and close each other's groups (false
// 'degraded' reports, hung HTTP responses, ERR_HTTP_HEADERS_SENT). Each run
// gets its own bucket and its own 20s timer, so no caller can hang and
// no run can contaminate another.
const EXPECTED = ["puffpai", "ollama", "homeassistant"];
const WAIT_MS = 20000;
const runs = context.get("runs") || {};
const tick = String(msg.health_tick || msg._msgid);
const topic = String(msg.topic || "unknown");
let run = runs[tick];
if (!run) {
    run = runs[tick] = { parts: {}, msg: null, timer: null };
    run.timer = setTimeout(function () {
        delete runs[tick];
        context.set("runs", runs);
        for (const t of EXPECTED) {
            if (!(t in run.parts)) {
                run.parts[t] = { __error: "no probe result (plumbing fault)" };
            }
        }
        const out = run.msg;
        out.payload = run.parts;
        node.warn("health run " + tick + " incomplete after " + WAIT_MS + "ms");
        node.send(out);
        node.done();
    }, WAIT_MS);
}
run.parts[topic] = msg.payload;
if (!run.msg) { run.msg = msg; }   // res/req are shared refs on clones
if (EXPECTED.every(function (t) { return t in run.parts; })) {
    clearTimeout(run.timer);
    delete runs[tick];
    context.set("runs", runs);
    const out = run.msg;
    out.payload = run.parts;
    node.send(out);
    node.done();
    return null;
}
context.set("runs", runs);
return null;
